// Core1 four-bridge spectra, complete A inputs and every B port permutation.
#include <bits/stdc++.h>
using namespace std;using E=vector<pair<int,int>>;int c;int zs[7]={7,11,13,14,2,4,8};int hs[3]={3,5,9};array<int,16>fa;E cur;vector<E>ns[7];unordered_set<uint64_t>good[7];struct A{E f;vector<int>p;array<vector<uint64_t>,7>spec;};vector<A>as;struct DSU{int p[40];bool ok=true;DSU(){iota(p,p+40,0);}int rt(int x){return p[x]==x?x:p[x]=rt(p[x]);}void add(int a,int b){a=rt(a);b=rt(b);if(a==b)ok=false;else p[a]=b;}};long long total=0,bad=0;ofstream out;
void genN(unsigned m,int f){if(!m){ns[f].push_back(cur);return;}int a=__builtin_ctz(m);m^=1u<<a;for(int j=0;j<4;j++){int b=a^(1<<j);if(m>>b&1){cur.push_back({a,b});genN(m^(1u<<b),f);cur.pop_back();}}}
void assessA(){A a;for(int v=1;v<16;v++)if(v!=3&&v!=5&&v!=9){if(fa[v]<0)a.p.push_back(v);else if(fa[v]>v)a.f.push_back({v,fa[v]});}for(int f=0;f<7;f++){set<uint64_t>ss;vector<int>ep=a.p;ep.insert(ep.end(),hs,hs+3);ep.push_back(zs[f]);for(auto&N:ns[f]){DSU d;for(auto[x,y]:a.f)d.add(x,y);for(auto[x,y]:N)d.add(x,y);if(!d.ok)continue;uint64_t code=0;bool ok=true;for(int i=0;i<c+4;i++){int mate=-1;for(int j=0;j<c+4;j++)if(i!=j&&d.rt(ep[i])==d.rt(ep[j])){if(mate>=0)ok=false;mate=j;}if(mate<0)ok=false;else code|=uint64_t(mate)<<(4*i);}if(ok)ss.insert(code);}a.spec[f]=vector<uint64_t>(ss.begin(),ss.end());}as.push_back(move(a));}
void genA(unsigned m,int skip){if(!m){if(!skip)assessA();return;}int a=__builtin_ctz(m);m^=1u<<a;if(skip)genA(m,skip-1);for(int b=a+1;b<16;b++)if(m>>b&1){fa[a]=b;fa[b]=a;genA(m^(1u<<b),skip);fa[a]=fa[b]=-1;}}
bool works(A&a,E&F,vector<int>&bp){for(int f=0;f<7;f++){int ep[16];for(int i=0;i<c;i++)ep[i]=bp[i];for(int i=0;i<3;i++)ep[c+i]=16+hs[i];ep[c+3]=16+zs[f];unsigned terminal=65532u;for(int z:{3,5,9,zs[f]})terminal&=~(1u<<z);for(auto code:a.spec[f]){DSU d;for(auto[x,y]:F)d.add(x,y);for(int z:{3,5,9,zs[f]})d.add(z,16+z);for(int i=0;i<c+4;i++){int j=(code>>(4*i))&15;if(j>i)d.add(ep[i],ep[j]);}if(!d.ok)continue;int first[40];fill(first,first+40,-1);uint64_t key=0;bool ok=true;for(int v=2;v<16;v++)if(terminal>>v&1){int r=d.rt(v);if(first[r]<0)first[r]=v;else if(first[r]>=16){ok=false;break;}else{int u=first[r];key|=uint64_t(u)<<(4*v);key|=uint64_t(v)<<(4*u);first[r]=16;}}if(ok&&good[f].count(key))return true;}}return false;}
int main(int argc,char**argv){if(argc!=2)return 2;c=stoi(argv[1]);for(int f=0;f<7;f++){genN(65534u&~(1u<<zs[f]),f);ifstream in("q4_five_avoided_3_5_9_1_"+to_string(zs[f])+".bin",ios::binary);unsigned char b[27];int n=0;while(in.read((char*)b,27)){n++;if(b[16]!=255){uint64_t key=0;for(int v=2;v<16;v++)if(b[v]!=255)key|=uint64_t(b[v])<<(4*v);good[f].insert(key);}}assert(n==945);}fa.fill(-1);genA(65534u&~(1u<<3)&~(1u<<5)&~(1u<<9),c);cerr<<"A "<<as.size()<<" ready\n";ifstream in("t15_core1_route_B"+to_string(c)+".txt");out.open("t15_core1_fourbridge_c"+to_string(c)+"_residual_inputs.bin",ios::binary);int x,y,bi=0;while(in>>x>>y){E F={{x,y}};unsigned covered=(1u<<x)|(1u<<y);for(int j=1;j<(14-c)/2;j++){in>>x>>y;F.push_back({x,y});covered|=(1u<<x)|(1u<<y);}vector<int>bp;for(int v=2;v<16;v++)if(!(covered>>v&1))bp.push_back(v);do{for(auto&a:as){total++;if(!works(a,F,bp)){bad++;for(auto[u,v]:a.f){out.put(char(2*u+1));out.put(char(2*v+1));}for(auto[u,v]:F){out.put(char(2*u));out.put(char(2*v));}for(int j=0;j<c;j++){out.put(char(2*a.p[j]+1));out.put(char(2*bp[j]));}}}}while(next_permutation(bp.begin(),bp.end()));cerr<<"B "<<++bi<<" total "<<total<<" bad "<<bad<<"\n";}cout<<"{\"c\":"<<c<<",\"A\":"<<as.size()<<",\"B\":"<<bi<<",\"inputs\":"<<total<<",\"residual\":"<<bad<<"}\n";}
